    """Return the median of a non-empty list of numbers.

    The input is not required to be sorted, and is not modified.
    """
    values = sorted(xs)
    middle = len(values) // 2
    if len(values) % 2:
        return float(values[middle])
    return (values[middle - 1] + values[middle]) / 2
