import re


_NON_ALNUM = re.compile(r"[^a-z0-9]+")


def slugify(text: str) -> str:
    """Convert *text* to a lowercase ASCII alphanumeric slug."""
    return _NON_ALNUM.sub("-", text.lower()).strip("-")
