import string


def word_counts(text: str) -> dict[str, int]:
    """Count whitespace-separated words after trimming punctuation."""
    counts: dict[str, int] = {}
    for word in text.split():
        word = word.strip(string.punctuation).lower()
        if word:
            counts[word] = counts.get(word, 0) + 1
    return counts
